import { mkdir, rm, writeFile } from 'node:fs/promises';
import { createReadStream, existsSync } from 'node:fs';
import { dirname, resolve, sep } from 'node:path';
import { Readable } from 'node:stream';
import type { StorageDriver } from './index.ts';

/** Stores files on local disk. On Coolify, mount a persistent volume at the root dir. */
export function localDriver(rootDir: string): StorageDriver {
	const root = resolve(rootDir);

	// Keys are generated by us, but never let one escape the root directory.
	const pathFor = (key: string) => {
		const p = resolve(root, key);
		if (!p.startsWith(root + sep)) throw new Error(`Invalid storage key: ${key}`);
		return p;
	};

	return {
		name: 'local',

		async put(key, data) {
			const p = pathFor(key);
			await mkdir(dirname(p), { recursive: true });
			await writeFile(p, data);
		},

		async get(key) {
			const p = pathFor(key);
			if (!existsSync(p)) return null;
			return Readable.toWeb(createReadStream(p)) as ReadableStream<Uint8Array>;
		},

		async delete(key) {
			await rm(pathFor(key), { force: true });
		}
	};
}
